const DEMO_NODES: Node<NodeData>[] = [
  { id: 'demo-1', type: 'blueprintNode', position: { x: -300, y: 50 }, data: { label: 'ERP Invoices', cardType: NodeCardType.TABLE, categoryId: 'cat-src', dataSourceId: 'src-erp', tags: ['tag-prod', 'tag-ext'], columns: [{ id: 'c1', name: 'Invoice_ID', typeId: 'ft-text', isKey: true }, { id: 'c2', name: 'Posted_Date', typeId: 'ft-date' }, { id: 'c3', name: 'Total_Amount', typeId: 'ft-number' }, { id: 'c4', name: 'Vendor_ID', typeId: 'ft-text' }], comment: 'Direct feed from SAP production instance.' } },
  { id: 'demo-2', type: 'blueprintNode', position: { x: -300, y: 450 }, data: { label: 'Customer Master', cardType: NodeCardType.TABLE, categoryId: 'cat-src', dataSourceId: 'src-crm', tags: ['tag-prod'], columns: [{ id: 'c5', name: 'Cust_ID', typeId: 'ft-text', isKey: true }, { id: 'c6', name: 'Tax_ID', typeId: 'ft-text' }, { id: 'c7', name: 'Region', typeId: 'ft-text' }] } },
  { id: 'demo-3', type: 'blueprintNode', position: { x: 100, y: 250 }, data: { label: 'Data Integrity Shield', cardType: NodeCardType.LOGIC_NOTE, categoryId: 'log-rule', tags: ['tag-crit'], description: 'Central validation gate for all incoming financial streams.', bulletPoints: ['Validate VAT ID against VIES registry', 'Check for duplicate Invoice_IDs in 24h window', 'Reject records with null Total_Amount'] } },
  { id: 'demo-4', type: 'blueprintNode', position: { x: 500, y: 250 }, data: { label: 'EU Tax Engine', cardType: NodeCardType.LOGIC_NOTE, categoryId: 'log-calc', tags: ['tag-prod', 'tag-crit'], description: 'Calculates regional VAT and cross-border duties.', bulletPoints: ['Apply 21% standard rate for local sales', 'Apply reverse charge logic for B2B cross-border', 'Round to 2 decimal places'] } },
  { id: 'demo-5', type: 'blueprintNode', position: { x: 900, y: 50 }, data: { label: 'Final Tax Ledger', cardType: NodeCardType.TABLE, categoryId: 'cat-std', tags: ['tag-prod'], columns: [{ id: 'c8', name: 'Entry_ID', typeId: 'ft-text', isKey: true }, { id: 'c9', name: 'Net_Amount', typeId: 'ft-number' }, { id: 'c10', name: 'VAT_Amount', typeId: 'ft-number' }, { id: 'c11', name: 'Status', typeId: 'ft-text' }] } },
  { id: 'demo-6', type: 'blueprintNode', position: { x: 900, y: 450 }, data: { label: 'VAT Compliance Report', cardType: NodeCardType.TABLE, categoryId: 'cat-std', tags: ['tag-ext'], columns: [{ id: 'c12', name: 'Report_ID', typeId: 'ft-text', isKey: true }, { id: 'c13', name: 'Period', typeId: 'ft-text' }, { id: 'c14', name: 'Total_VAT_Collected', typeId: 'ft-number' }] } }
];

const DEMO_EDGES: Edge[] = [
  { id: 'e1', source: 'demo-1', target: 'demo-3', sourceHandle: 'r-s', targetHandle: 'l-t', type: 'blueprintEdge', data: { typeId: 'conn-std' }, markerEnd: { type: MarkerType.ArrowClosed, color: '#94a3b8' } },
  { id: 'e2', source: 'demo-2', target: 'demo-3', sourceHandle: 'r-s', targetHandle: 'l-t', type: 'blueprintEdge', data: { typeId: 'conn-std' }, markerEnd: { type: MarkerType.ArrowClosed, color: '#94a3b8' } },
  { id: 'e3', source: 'demo-3', target: 'demo-4', sourceHandle: 'r-s', targetHandle: 'l-t', type: 'blueprintEdge', label: 'Validated Flow', data: { typeId: 'conn-crit' }, markerEnd: { type: MarkerType.ArrowClosed, color: '#dc2626' } },
  { id: 'e4', source: 'demo-4', target: 'demo-5', sourceHandle: 'r-s', targetHandle: 'l-t', type: 'blueprintEdge', data: { typeId: 'conn-std' }, markerEnd: { type: MarkerType.ArrowClosed, color: '#94a3b8' } },
  { id: 'e5', source: 'demo-4', target: 'demo-6', sourceHandle: 'r-s', targetHandle: 'l-t', type: 'blueprintEdge', data: { typeId: 'conn-std' }, markerEnd: { type: MarkerType.ArrowClosed, color: '#94a3b8' } }
];

const DEFAULT_APPEARANCE: AppearanceSettings = {
  language: 'en',
  canvasBgColor: '#f8fafc',
  headerFontSize: 'sm',
  contentFontSize: 'sm',
  userName: 'Blueprinter',
  organizationName: 'Data Blueprint Corp',
  isLegendExpanded: true,
  maxFieldsToShow: 6
};

const MULTI_PROJECT_STORAGE_KEY = 'whitebox_multi_project_v1';
const APPEARANCE_STORAGE_KEY = 'whitebox_appearance_v1';
const HIDE_ALL_VALUE = '__HIDE_ALL__';
const CANVAS_PADDING = 0.35;

function BlueprintStudio() {
  const { fitView } = useReactFlow();
  const [viewType, setViewType] = useState<ViewType>('canvas');
  const [searchQuery, setSearchQuery] = useState('');
  const toolbarRef = useRef<HTMLDivElement>(null);
  const [highlightedNodeId, setHighlightedNodeId] = useState<string | null>(null);
  const [showExportModal, setShowExportModal] = useState(false);

  // Multi-project core state
  const [projects, setProjects] = useState<ProjectMetadata[]>(() => {
    const saved = localStorage.getItem(MULTI_PROJECT_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.projects && Array.isArray(parsed.projects)) return parsed.projects;
      } catch (e) { console.error("Failed to parse projects metadata", e); }
    }
    return [{ id: 'p1', name: 'Project 1' }];
  });

  const [activeProjectId, setActiveProjectId] = useState<string>(() => {
    const saved = localStorage.getItem(MULTI_PROJECT_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.activeProjectId) return parsed.activeProjectId;
      } catch (e) { console.error("Failed to parse active project id", e); }
    }
    return 'p1';
  });

  const [projectDataMap, setProjectDataMap] = useState<Record<string, ProjectData>>(() => {
    const saved = localStorage.getItem(MULTI_PROJECT_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.dataMap) return parsed.dataMap;
      } catch (e) { console.error("Failed to parse project data map", e); }
    }
    return {
      'p1': {
        nodes: DEMO_NODES,
        edges: DEMO_EDGES,
        settings: DEFAULT_SETTINGS,
        activeTableFilters: [],
        activeLogicFilters: [],
        activeEdgeFilters: [],
        activeTagFilters: []
      }
    };
  });

  const activeData = projectDataMap[activeProjectId] || {
    nodes: [], edges: [], settings: DEFAULT_SETTINGS,
    activeTableFilters: [], activeLogicFilters: [], activeEdgeFilters: [], activeTagFilters: []
  };

  const [nodes, setNodes] = useState<Node<NodeData>[]>(activeData.nodes);
  const [edges, setEdges] = useState<Edge[]>(activeData.edges);
  const [settings, setSettings] = useState<GlobalSettings>(activeData.settings);
  const [activeTableFilters, setActiveTableFilters] = useState<string[]>(activeData.activeTableFilters || []);
  const [activeLogicFilters, setActiveLogicFilters] = useState<string[]>(activeData.activeLogicFilters || []);
  const [activeEdgeFilters, setActiveEdgeFilters] = useState<string[]>(activeData.activeEdgeFilters || []);
  const [activeTagFilters, setActiveTagFilters] = useState<string[]>(activeData.activeTagFilters || []);

  const [appearance, setAppearance] = useState<AppearanceSettings>(() => {
    const saved = localStorage.getItem(APPEARANCE_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...DEFAULT_APPEARANCE, ...parsed };
      } catch (e) { console.error("Failed to parse saved appearance", e); }
    }
    return DEFAULT_APPEARANCE;
  });

  const [openMenuType, setOpenMenuType] = useState<'project' | 'table' | 'logic' | 'edge' | 'tag' | 'add' | 'io' | null>(null);

  const t = (key: keyof typeof translations.en) => translations[appearance.language][key] || key;

  const allCategories = useMemo(() => [
    ...settings.tableCategories,
    ...settings.logicCategories
  ], [settings.tableCategories, settings.logicCategories]);

  // Sync back to map when states change
  useEffect(() => {
    setProjectDataMap(prev => ({
      ...prev,
      [activeProjectId]: {
        nodes, edges, settings, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters
      }
    }));
  }, [nodes, edges, settings, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters, activeProjectId]);

  // Handle local storage persistence
  useEffect(() => {
    const bundle = { projects, activeProjectId, dataMap: projectDataMap };
    localStorage.setItem(MULTI_PROJECT_STORAGE_KEY, JSON.stringify(bundle));
  }, [projects, activeProjectId, projectDataMap]);

  useEffect(() => {
    localStorage.setItem(APPEARANCE_STORAGE_KEY, JSON.stringify(appearance));
  }, [appearance]);

  const switchProject = (id: string) => {
    const targetData = projectDataMap[id];
    if (targetData) {
      setActiveProjectId(id);
      setNodes(targetData.nodes);
      setEdges(targetData.edges);
      setSettings(targetData.settings);
      setActiveTableFilters(targetData.activeTableFilters || []);
      setActiveLogicFilters(targetData.activeLogicFilters || []);
      setActiveEdgeFilters(targetData.activeEdgeFilters || []);
      setActiveTagFilters(targetData.activeTagFilters || []);
      setOpenMenuType(null);
    }
  };

  const createNewProject = () => {
    const id = `p-${Date.now()}`;
    const name = `Project ${projects.length + 1}`;
    const newMetadata = { id, name };
    const newData: ProjectData = {
      nodes: [],
      edges: [],
      settings: DEFAULT_SETTINGS,
      activeTableFilters: [],
      activeLogicFilters: [],
      activeEdgeFilters: [],
      activeTagFilters: []
    };
    setProjects(prev => [...prev, newMetadata]);
    setProjectDataMap(prev => ({ ...prev, [id]: newData }));
    switchProject(id);
  };

  const onNodesChange = useCallback((changes: NodeChange[]) => setNodes((nds) => applyNodeChanges(changes, nds)), []);
  const onEdgesChange = useCallback((changes: EdgeChange[]) => setEdges((eds) => applyEdgeChanges(changes, eds)), []);
  const onConnect = useCallback((params: Connection) => {
    const defaultType = settings.connectionTypes[0];
    setEdges((eds) => addEdge({ 
      ...params, 
      type: 'blueprintEdge',
      data: { typeId: defaultType.id },
      markerEnd: { type: MarkerType.ArrowClosed, color: defaultType.color }
    }, eds));
  }, [settings]);

  const handleDuplicateNode = useCallback((id: string) => {
    setNodes((nds) => {
      const nodeToCopy = nds.find((n) => n.id === id);
      if (!nodeToCopy) return nds;
      return [...nds, { ...nodeToCopy, id: `dup-${Date.now()}`, position: { x: nodeToCopy.position.x + 40, y: nodeToCopy.position.y + 40 }, data: { ...nodeToCopy.data, label: `${nodeToCopy.data.label}_Copy` } }];
    });
  }, []);

  const handleAutoAlign = useCallback(() => {
    if (viewType !== 'canvas') setViewType('canvas');
    setTimeout(() => { fitView({ padding: CANVAS_PADDING, duration: 800 }); }, 50);
  }, [fitView, viewType]);

  const handleLocateOnCanvas = useCallback((nodeId: string) => {
    setViewType('canvas');
    setHighlightedNodeId(nodeId);
    setTimeout(() => { fitView({ nodes: [{ id: nodeId }], duration: 1200, padding: 0.5 }); }, 100);
    setTimeout(() => { setHighlightedNodeId(null); }, 4000);
  }, [fitView]);

  const handleResetFilters = useCallback(() => {
    setActiveTableFilters([]);
    setActiveLogicFilters([]);
    setActiveEdgeFilters([]);
    setActiveTagFilters([]);
    setSearchQuery('');
    setOpenMenuType(null);
  }, []);

  const getFilterDisplay = (type: 'table' | 'logic' | 'edge' | 'tag') => {
    let current: string[] = [];
    if (type === 'table') current = activeTableFilters;
    else if (type === 'logic') current = activeLogicFilters;
    else if (type === 'edge') current = activeEdgeFilters;
    else if (type === 'tag') current = activeTagFilters;

    if (current.length === 0) return t('all');
    if (current.includes(HIDE_ALL_VALUE)) return t('hide_all');
    if (current.length === 1) {
      if (type === 'table') return settings.tableCategories.find(c => c.id === current[0])?.name || t('all');
      if (type === 'logic') return settings.logicCategories.find(c => c.id === current[0])?.name || t('all');
      if (type === 'edge') return settings.connectionTypes.find(c => c.id === current[0])?.name || t('all');
      if (type === 'tag') return settings.tags.find(c => c.id === current[0])?.name || t('all');
    }
    return `${current.length} selected`;
  };

  const getFilterCount = (type: 'table' | 'logic' | 'edge' | 'tag') => {
    if (type === 'table') return activeTableFilters.length;
    if (type === 'logic') return activeLogicFilters.length;
    if (type === 'edge') return activeEdgeFilters.length;
    if (type === 'tag') return activeTagFilters.length;
    return 0;
  };

  const toggleMultiFilter = (id: string, current: string[], setter: (val: string[]) => void) => {
    if (id === HIDE_ALL_VALUE) setter(current.includes(HIDE_ALL_VALUE) ? [] : [HIDE_ALL_VALUE]);
    else {
      const filtered = current.filter(x => x !== HIDE_ALL_VALUE);
      if (filtered.includes(id)) setter(filtered.filter(x => x !== id));
      else setter([...filtered, id]);
    }
  };

  const exportToExcel = () => {
    const wb = XLSX.utils.book_new();
    const allProjectsRows: any[] = [];
    const allNodesRows: any[] = [];
    const allEdgesRows: any[] = [];
    const allTableCatsRows: any[] = [];
    const allLogicCatsRows: any[] = [];
    const allConnTypesRows: any[] = [];
    const allDataSourcesRows: any[] = [];
    const allFieldTypesRows: any[] = [];
    const allTagsRows: any[] = [];

    projects.forEach(p => {
      const data = projectDataMap[p.id];
      if (!data) return;
      allProjectsRows.push({ 
        ProjectID: p.id, 
        ProjectName: p.name,
        TableFilters: (data.activeTableFilters || []).join('|'),
        LogicFilters: (data.activeLogicFilters || []).join('|'),
        EdgeFilters: (data.activeEdgeFilters || []).join('|'),
        TagFilters: (data.activeTagFilters || []).join('|')
      });
      data.nodes.forEach(n => allNodesRows.push({ ProjectID: p.id, ID: n.id, Label: n.data.label, Type: n.data.cardType, CatID: n.data.categoryId || '', X: n.position.x, Y: n.position.y, Columns: n.data.columns?.map((c: any) => `${c.name}:${c.typeId || ''}:${c.isKey ? 'K' : ''}`).join('|') || '', Desc: n.data.description || '', Bullets: n.data.bulletPoints?.join('|') || '', Comment: n.data.comment || '', DataSourceID: n.data.dataSourceId || '', Tags: n.data.tags?.join('|') || '' }));
      data.edges.forEach(e => allEdgesRows.push({ ProjectID: p.id, ID: e.id, Source: e.source, Target: e.target, SourceHandle: e.sourceHandle || '', TargetHandle: e.targetHandle || '', Label: e.label || '', TypeID: e.data?.typeId || '', HasArrow: e.markerEnd ? 'YES' : 'NO' }));
      data.settings.tableCategories.forEach(c => allTableCatsRows.push({ ...c, ProjectID: p.id }));
      data.settings.logicCategories.forEach(c => allLogicCatsRows.push({ ...c, ProjectID: p.id }));
      data.settings.connectionTypes.forEach(c => allConnTypesRows.push({ ...c, ProjectID: p.id }));
      data.settings.dataSources.forEach(c => allDataSourcesRows.push({ ...c, ProjectID: p.id }));
      data.settings.fieldTypes.forEach(c => allFieldTypesRows.push({ ...c, ProjectID: p.id }));
      (data.settings.tags || []).forEach(c => allTagsRows.push({ ...c, ProjectID: p.id }));
    });

    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allProjectsRows), "Projects");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allNodesRows), "Nodes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allEdgesRows), "Edges");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allTableCatsRows), "TableCategories");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allLogicCatsRows), "LogicCategories");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allConnTypesRows), "ConnectionTypes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allDataSourcesRows), "DataSources");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allFieldTypesRows), "FieldTypes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(allTagsRows), "Tags");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet([appearance]), "Appearance");
    XLSX.writeFile(wb, `WhiteBox_Export_${new Date().getTime()}.xlsx`);
    setOpenMenuType(null);
  };

  const importFromExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const workbook = XLSX.read(evt.target?.result, { type: 'binary' });
      const projectsRaw = workbook.Sheets["Projects"] ? XLSX.utils.sheet_to_json(workbook.Sheets["Projects"]) as any[] : [{ ProjectID: 'p1', ProjectName: 'Imported' }];
      const nodesRaw = workbook.Sheets["Nodes"] ? XLSX.utils.sheet_to_json(workbook.Sheets["Nodes"]) as any[] : [];
      const edgesRaw = workbook.Sheets["Edges"] ? XLSX.utils.sheet_to_json(workbook.Sheets["Edges"]) as any[] : [];
      const tableCatsRaw = workbook.Sheets["TableCategories"] ? XLSX.utils.sheet_to_json(workbook.Sheets["TableCategories"]) as any[] : [];
      const logicCatsRaw = workbook.Sheets["LogicCategories"] ? XLSX.utils.sheet_to_json(workbook.Sheets["LogicCategories"]) as any[] : [];
      const connTypesRaw = workbook.Sheets["ConnectionTypes"] ? XLSX.utils.sheet_to_json(workbook.Sheets["ConnectionTypes"]) as any[] : [];
      const dataSourcesRaw = workbook.Sheets["DataSources"] ? XLSX.utils.sheet_to_json(workbook.Sheets["DataSources"]) as any[] : [];
      const fieldTypesRaw = workbook.Sheets["FieldTypes"] ? XLSX.utils.sheet_to_json(workbook.Sheets["FieldTypes"]) as any[] : [];
      const tagsRaw = workbook.Sheets["Tags"] ? XLSX.utils.sheet_to_json(workbook.Sheets["Tags"]) as any[] : [];
      const newProjects: ProjectMetadata[] = projectsRaw.map(p => ({ id: String(p.ProjectID), name: String(p.ProjectName) }));
      const newDataMap: Record<string, ProjectData> = {};
      newProjects.forEach(p => {
        const pid = p.id;
        const pRaw = projectsRaw.find(pr => String(pr.ProjectID) === pid);
        const settings: GlobalSettings = {
          tableCategories: tableCatsRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest),
          logicCategories: logicCatsRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest),
          connectionTypes: connTypesRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest),
          dataSources: dataSourcesRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest),
          fieldTypes: fieldTypesRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest),
          tags: tagsRaw.filter(c => String(c.ProjectID) === pid).map(({ ProjectID, ...rest }) => rest)
        };
        const nodes = nodesRaw.filter(n => String(n.ProjectID) === pid).map(n => ({ id: String(n.ID), type: 'blueprintNode', position: { x: Number(n.X), y: Number(n.Y) }, data: { label: n.Label, cardType: n.Type, categoryId: n.CatID, columns: n.Columns ? n.Columns.split('|').map((colStr: string, i: number) => { const [name, typeId, key] = colStr.split(':'); return { id: String(i), name, typeId: typeId || undefined, isKey: key === 'K' }; }) : [], description: n.Desc, bulletPoints: n.Bullets ? n.Bullets.split('|') : [], comment: n.Comment || '', dataSourceId: n.DataSourceID || '', tags: n.Tags ? n.Tags.split('|') : [] } }));
        const edges = edgesRaw.filter(e => String(e.ProjectID) === pid).map(e => { const cType = settings.connectionTypes.find(t => t.id === e.TypeID); return { id: String(e.ID), source: String(e.Source), target: String(e.Target), sourceHandle: e.SourceHandle || null, targetHandle: e.TargetHandle || null, label: e.Label, type: 'blueprintEdge', data: { typeId: e.TypeID }, markerEnd: e.HasArrow === 'YES' ? { type: MarkerType.ArrowClosed, color: cType?.color || '#94a3b8' } : undefined }; });
        newDataMap[pid] = { nodes, edges, settings, activeTableFilters: pRaw?.TableFilters ? pRaw.TableFilters.split('|') : [], activeLogicFilters: pRaw?.LogicFilters ? pRaw.LogicFilters.split('|') : [], activeEdgeFilters: pRaw?.EdgeFilters ? pRaw.EdgeFilters.split('|') : [], activeTagFilters: pRaw?.TagFilters ? pRaw.TagFilters.split('|') : [] };
      });
      setProjects(newProjects); setProjectDataMap(newDataMap); if (newProjects[0]) switchProject(newProjects[0].id); setOpenMenuType(null);
    };
    reader.readAsBinaryString(file);
  };

  const isNodeVisible = useCallback((node: Node<NodeData>) => {
    const { data } = node;
    const isTable = data.cardType === NodeCardType.TABLE;
    const isLogic = data.cardType === NodeCardType.LOGIC_NOTE;
    if (isTable && activeTableFilters.length > 0) { if (activeTableFilters.includes(HIDE_ALL_VALUE)) return false; if (data.categoryId && !activeTableFilters.includes(data.categoryId)) return false; }
    if (isLogic && activeLogicFilters.length > 0) { if (activeLogicFilters.includes(HIDE_ALL_VALUE)) return false; if (data.categoryId && !activeLogicFilters.includes(data.categoryId)) return false; }
    if (activeTagFilters.length > 0) { if (activeTagFilters.includes(HIDE_ALL_VALUE)) return false; if (!data.tags?.some(tagId => activeTagFilters.includes(tagId))) return false; }
    if (searchQuery.trim()) { const q = searchQuery.toLowerCase(); if (!data.label.toLowerCase().includes(q) && !data.description?.toLowerCase().includes(q) && !data.columns?.some(c => c.name.toLowerCase().includes(q))) return false; }
    return true;
  }, [activeTableFilters, activeLogicFilters, activeTagFilters, searchQuery]);

  const filteredNodes = useMemo(() => nodes.filter(isNodeVisible), [nodes, isNodeVisible]);
  const nodesWithActions = useMemo(() => filteredNodes.map(n => ({ ...n, data: { ...n.data, onEdit: (id: string) => setEditingNode(id), onDelete: (id: string) => setNodes(nds => nds.filter(node => node.id !== id)), onDuplicate: handleDuplicateNode, settings, appearance, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters, highlightedNodeId } })), [filteredNodes, settings, appearance, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters, handleDuplicateNode, highlightedNodeId]);
  const edgesWithActions = useMemo(() => edges.map(e => { const sourceNode = nodes.find(n => n.id === e.source); const targetNode = nodes.find(n => n.id === e.target); return { ...e, data: { ...e.data, onEdit: (id: string) => setEditingEdge(id), onDelete: (id: string) => setEdges(eds => eds.filter(edge => edge.id !== id)), settings, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters, sourceCategoryId: sourceNode?.data.categoryId, targetCategoryId: targetNode?.data.categoryId, sourceTags: sourceNode?.data.tags, targetTags: targetNode?.data.tags } }; }), [edges, settings, activeTableFilters, activeLogicFilters, activeEdgeFilters, activeTagFilters, nodes]);

  const [editingNode, setEditingNode] = useState<string | null>(null);
  const [editingEdge, setEditingEdge] = useState<string | null>(null);
  const [showStudioSettings, setShowStudioSettings] = useState<any>(null);

  const currentProjectName = projects.find(p => p.id === activeProjectId)?.name || 'Project';

  const addNode = (type: NodeCardType) => {
    const id = Date.now().toString();
    let defaultCatId = undefined;
    if (type === NodeCardType.TABLE) defaultCatId = (settings.tableCategories.find(c => c.isDefault) || settings.tableCategories[0]).id;
    else if (type === NodeCardType.LOGIC_NOTE) defaultCatId = (settings.logicCategories.find(c => c.isDefault) || settings.logicCategories[0]).id;
    setNodes((nds) => [...nds, { id, type: 'blueprintNode', position: { x: 100, y: 100 }, data: { label: `New ${type.toLowerCase()}`, cardType: type, categoryId: defaultCatId, columns: type === NodeCardType.TABLE ? [{ id: '1', name: 'New Field', isKey: false }] : [], description: '', bulletPoints: [], comment: '', dataSourceId: '', tags: [] } }]);
    setOpenMenuType(null);
  };

  return (
    <div className="w-full h-full bg-slate-50 relative overflow-hidden" style={{ backgroundColor: appearance.canvasBgColor }}>
      <main className="w-full h-full relative" id="studio-main-viewport">
        <div className="absolute inset-x-0 top-0 p-2 lg:p-4 2xl:p-6 flex items-center justify-between pointer-events-none z-30 transition-all duration-300" ref={toolbarRef}>
          <div className="flex items-center gap-1.5 lg:gap-2 2xl:gap-3 pointer-events-auto flex-nowrap min-w-0">
            {/* Project Picker */}
            <div className="relative flex-shrink-0">
              <button onClick={() => setOpenMenuType(openMenuType === 'project' ? null : 'project')} className={`flex items-center justify-center gap-3 px-2 2xl:px-5 py-1.5 lg:py-2 bg-indigo-600 text-white rounded-full shadow-lg hover:shadow-xl hover:bg-indigo-700 transition-all transform active:scale-95 group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 ${openMenuType === 'project' ? 'bg-slate-900' : ''}`} title="Projects">
                <FolderOpen size={20} strokeWidth={2.5} />
                <div className="hidden 2xl:flex items-center pr-1"><span className="text-lg font-black text-white transition-colors leading-none tracking-tight truncate max-w-[120px]">{currentProjectName}</span><ChevronDown size={14} className={`ml-2 text-indigo-200 transition-transform ${openMenuType === 'project' ? 'rotate-180' : ''}`} /></div>
              </button>
              {openMenuType === 'project' && (<div className="absolute top-full left-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200"><div className="px-4 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50">Select Project</div><div className="max-h-64 overflow-y-auto custom-scrollbar">{projects.map(p => (<button key={p.id} onClick={() => switchProject(p.id)} className={`w-full flex items-center justify-between px-4 py-3 text-sm font-bold transition-colors ${activeProjectId === p.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-700 hover:bg-slate-50'}`}><span className="truncate flex-1 text-left">{p.name}</span>{activeProjectId === p.id && <Check size={14} className="ml-2 shrink-0" />}</button>))}</div><div className="h-px bg-slate-100 my-1" /><button onClick={createNewProject} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-emerald-600 hover:bg-emerald-50 transition-colors"><Plus size={16} /><span className="text-left">Create New Project</span></button></div>)}
            </div>
            <div className="h-6 w-px bg-slate-200 mx-0.5 lg:mx-1 flex-shrink-0" />

            {/* Create Node */}
            <div className="relative flex-shrink-0">
              <button onClick={() => setOpenMenuType(openMenuType === 'add' ? null : 'add')} className={`flex items-center justify-center gap-3 px-2 2xl:px-4 py-1.5 lg:py-2 bg-blue-600 text-white rounded-full shadow-lg hover:shadow-xl hover:bg-blue-700 transition-all transform active:scale-95 group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 ${openMenuType === 'add' ? 'bg-slate-900' : ''}`} title={t('add_nodes')}><Plus size={22} strokeWidth={2.5} /><div className="hidden 2xl:flex items-center pr-1"><span className="text-lg font-black text-white transition-colors leading-none tracking-tight">{t('add_nodes')}</span></div></button>
              {openMenuType === 'add' && (<div className="absolute top-full left-0 mt-3 w-56 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200"><button onClick={() => { addNode(NodeCardType.TABLE); }} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-blue-50 hover:text-blue-600 transition-colors"><Database size={16} /><span className="text-left">{t('data_table')}</span></button><button onClick={() => { addNode(NodeCardType.LOGIC_NOTE); }} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-purple-50 hover:text-purple-600 transition-colors"><FileText size={16} /><span className="text-left">{t('logic_node')}</span></button></div>)}
            </div>

            {/* Import / Export */}
            <div className="relative flex-shrink-0">
              <button onClick={() => setOpenMenuType(openMenuType === 'io' ? null : 'io')} className={`flex items-center justify-center gap-3 px-2 2xl:px-4 py-1.5 lg:py-2 bg-emerald-600 text-white rounded-full shadow-lg hover:shadow-xl hover:bg-emerald-700 transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 border border-emerald-500/30 active:scale-95 ${openMenuType === 'io' ? 'bg-slate-900 border-slate-700' : ''}`} title={t('import_export')}><ArrowUpDown size={22} strokeWidth={2.5} /><div className="hidden 2xl:flex items-center pr-1"><span className="text-lg font-black text-white transition-colors leading-none tracking-tight">{t('import_export')}</span></div></button>
              {openMenuType === 'io' && (<div className="absolute top-full left-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200"><button onClick={exportToExcel} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors"><Download size={16} className="text-blue-600" /><span className="text-left">{t('export_project')}</span></button><label className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors cursor-pointer"><Upload size={16} className="text-emerald-600" /><span className="text-left">{t('import_xlsx')}</span><input type="file" className="hidden" accept=".xlsx, .xls" onChange={importFromExcel} /></label><button onClick={() => { setOpenMenuType(null); setShowExportModal(true); }} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors"><Camera size={16} className="text-indigo-600" /><span className="text-left">{t('export_image')}</span></button></div>)}
            </div>

            <div className="h-6 w-px bg-slate-200 mx-0.5 lg:mx-1 flex-shrink-0" />

            <button onClick={() => setShowStudioSettings({ initialTab: 'general' })} className="flex items-center justify-center gap-3 px-2 2xl:px-4 py-1.5 lg:py-2 bg-slate-900 text-white rounded-full shadow-lg hover:shadow-xl transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 border border-slate-700 active:scale-95" title={t('general_settings')}><Settings2 size={22} /></button>
            <button onClick={handleAutoAlign} className="flex items-center justify-center gap-3 px-2 2xl:px-4 py-1.5 lg:py-2 bg-blue-600 text-white rounded-full shadow-lg hover:shadow-xl hover:bg-blue-700 transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 border border-blue-500/30 active:scale-95" title={t('auto_align')}><Maximize size={22} strokeWidth={2.5} /></button>

            <div className="h-6 w-px bg-slate-200 mx-0.5 lg:mx-1 flex-shrink-0" />

            {/* Filters Restoration */}
            <button onClick={handleResetFilters} className="flex items-center justify-center gap-3 px-4 py-1.5 lg:py-2 bg-white border border-slate-200 rounded-full shadow hover:shadow-md transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto" title={t('reset_filters')}>
              <div className="flex items-center gap-3">
                <div className="w-7 h-7 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center group-hover:rotate-[-45deg] transition-transform">
                  <RotateCcw size={16} strokeWidth={2.5} />
                </div>
                <div className="hidden 2xl:flex flex-col items-start">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-0.5">{t('filters_label')}</span>
                  <span className="text-xs font-bold text-slate-700">{t('reset_filters')}</span>
                </div>
              </div>
            </button>

            {['tag', 'table', 'logic', 'edge'].map((type: any) => (
              <div className="relative flex-shrink-0" key={type}>
                <button onClick={() => setOpenMenuType(openMenuType === type ? null : type)} className={`flex items-center justify-center gap-3 px-4 py-1.5 lg:py-2 bg-white border border-slate-200 rounded-full shadow hover:shadow-md transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto relative ${openMenuType === type ? 'ring-2 ring-indigo-500/20' : ''}`}>
                  <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${type === 'tag' ? 'bg-emerald-50 text-emerald-600' : type === 'table' ? 'bg-blue-50 text-blue-600' : type === 'logic' ? 'bg-purple-50 text-purple-600' : 'bg-slate-50 text-slate-600'}`}>
                    {type === 'tag' ? <TagIcon size={16} /> : type === 'table' ? <Database size={16} /> : type === 'logic' ? <FileText size={16} /> : <Link2 size={16} />}
                  </div>
                  <div className="flex flex-col items-start hidden 2xl:flex">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-0.5">{t(type === 'tag' ? 'tags' : type === 'table' ? 'data_table' : type === 'logic' ? 'logic_node' : 'link_classification')}</span>
                    <span className="text-xs font-bold text-slate-700 truncate max-w-[80px]">{getFilterDisplay(type)}</span>
                  </div>
                  <ChevronDown size={14} className={`text-slate-400 transition-transform ${openMenuType === type ? 'rotate-180' : ''} hidden 2xl:block`} />
                  {getFilterCount(type) > 0 && <span className="absolute -top-1 -right-1 flex h-4 min-w-[16px] px-1 items-center justify-center rounded-full bg-slate-900 text-[9px] font-black text-white 2xl:hidden shadow-sm border border-white z-20 leading-none">{getFilterCount(type)}</span>}
                </button>
                {openMenuType === type && (<div className="absolute top-full left-0 mt-2 w-64 bg-white rounded-2xl shadow-2xl border border-slate-100 py-2 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200"><button onClick={() => (type === 'tag' ? setActiveTagFilters([]) : type === 'table' ? setActiveTableFilters([]) : type === 'logic' ? setActiveLogicFilters([]) : setActiveEdgeFilters([]))} className="w-full flex items-center justify-between px-4 py-2.5 text-sm font-semibold transition-colors hover:bg-slate-50 text-slate-600 text-left"><div className="flex items-center gap-3"><div className="w-2.5 h-2.5 rounded-full bg-slate-200" /><span className="flex-1">{t('all')}</span></div>{(type === 'tag' ? activeTagFilters : type === 'table' ? activeTableFilters : type === 'logic' ? activeLogicFilters : activeEdgeFilters).length === 0 && <Check size={14} />}</button><button onClick={() => toggleMultiFilter(HIDE_ALL_VALUE, (type === 'tag' ? activeTagFilters : type === 'table' ? activeTableFilters : type === 'logic' ? activeLogicFilters : activeEdgeFilters), (type === 'tag' ? setActiveTagFilters : type === 'table' ? setActiveTableFilters : type === 'logic' ? setActiveLogicFilters : setActiveEdgeFilters))} className="w-full flex items-center justify-between px-4 py-2.5 text-sm font-semibold transition-colors hover:bg-slate-50 text-slate-600 text-left"><div className="flex items-center gap-3"><div className="w-2.5 h-2.5 rounded-full bg-slate-900" /><span className="flex-1">{t('hide_all')}</span></div>{(type === 'tag' ? activeTagFilters : type === 'table' ? activeTableFilters : type === 'logic' ? activeLogicFilters : activeEdgeFilters).includes(HIDE_ALL_VALUE) && <Check size={14} />}</button><div className="h-px bg-slate-50 my-1 mx-4" />{(type === 'tag' ? settings.tags : type === 'table' ? settings.tableCategories : type === 'logic' ? settings.logicCategories : settings.connectionTypes).map((item: any) => (<button key={item.id} onClick={() => toggleMultiFilter(item.id, (type === 'tag' ? activeTagFilters : type === 'table' ? activeTableFilters : type === 'logic' ? activeLogicFilters : activeEdgeFilters), (type === 'tag' ? setActiveTagFilters : type === 'table' ? setActiveTableFilters : type === 'logic' ? setActiveLogicFilters : setActiveEdgeFilters))} className="w-full flex items-center justify-between px-4 py-2.5 text-sm font-semibold transition-colors hover:bg-slate-50 text-slate-600 text-left"><div className="flex items-center gap-3"><div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.color }} /><span className="flex-1">{item.name}</span></div>{(type === 'tag' ? activeTagFilters : type === 'table' ? activeTableFilters : type === 'logic' ? activeLogicFilters : activeEdgeFilters).includes(item.id) && <Check size={14} />}</button>))}</div>)}
              </div>
            ))}
          </div>
          <div className="flex items-center gap-1.5 lg:gap-2 2xl:gap-3 pointer-events-auto flex-nowrap shrink-0"><button onClick={() => setViewType(viewType === 'canvas' ? 'catalog' : 'canvas')} className={`flex items-center justify-center gap-3 px-2 2xl:px-4 py-1.5 lg:py-2 bg-indigo-600 text-white rounded-full shadow-lg hover:shadow-xl hover:bg-indigo-700 transition-all group h-10 lg:h-12 2xl:w-auto aspect-square 2xl:aspect-auto flex-shrink-0 border border-indigo-500/30 active:scale-95 ${viewType === 'catalog' ? 'bg-slate-900 border-slate-700' : ''}`} title={t('view_swap')}>{viewType === 'canvas' ? <LayoutList size={22} strokeWidth={2.5} /> : <MapIcon size={22} strokeWidth={2.5} />}</button></div>
        </div>

        {viewType === 'canvas' ? (<><ReactFlow nodes={nodesWithActions} edges={edgesWithActions} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} onConnect={onConnect} nodeTypes={nodeTypes} edgeTypes={edgeTypes} fitView fitViewOptions={{ padding: CANVAS_PADDING }} minZoom={0.05} maxZoom={4} onPaneClick={() => setOpenMenuType(null)} onMoveStart={() => setOpenMenuType(null)} className="bg-transparent" defaultEdgeOptions={{ type: 'blueprintEdge', markerEnd: { type: MarkerType.ArrowClosed, color: '#94a3b8' } }}><Background color="#cbd5e1" variant={BackgroundVariant.Dots} gap={24} size={1} /><Controls position="bottom-left" /></ReactFlow><div className="absolute bottom-6 left-[72px] pointer-events-none select-none z-10 opacity-[0.12] flex items-center gap-[clamp(0.4rem,1.2vw,0.8rem)] transition-opacity duration-500 animate-in fade-in slide-in-from-left-4"><PackageOpen strokeWidth={1.5} className="text-slate-900 shrink-0" style={{ width: 'clamp(26px, 4.8vw, 52px)', height: 'clamp(26px, 4.8vw, 52px)' }} /><div className="hidden sm:flex flex-col"><h1 className="font-black text-slate-900 leading-none tracking-tight" style={{ fontSize: 'clamp(1rem, 2.8vw, 1.8rem)' }}>WhiteBox</h1><p className="font-black text-slate-600 uppercase tracking-widest mt-1" style={{ fontSize: 'clamp(7px, 0.96vw, 8px)' }}>Documentation Studio</p></div></div><Legend settings={settings} appearance={appearance} onUpdateAppearance={setAppearance} /></>) : (<div className="w-full h-full overflow-y-auto px-6 py-32 lg:px-12 animate-in fade-in duration-500 custom-scrollbar" style={{ backgroundColor: appearance.canvasBgColor }}><div className="max-w-4xl mx-auto mb-12"><div className="relative group"><div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-400 group-focus-within:text-blue-500 transition-colors"><Search size={22} strokeWidth={2.5} /></div><input type="text" placeholder={t('search_placeholder')} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full h-16 pl-16 pr-8 bg-white/80 backdrop-blur-md border border-slate-200 rounded-full shadow-lg shadow-slate-200/50 text-lg font-bold text-slate-800 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all placeholder-slate-300" /></div></div>{allCategories.map((cat) => { const catNodes = filteredNodes.filter(n => n.data.categoryId === cat.id); if (catNodes.length === 0) return null; return (<section key={cat.id} className="max-w-7xl mx-auto mb-16 animate-in slide-in-from-bottom-4 duration-500"><div className="flex items-center gap-4 mb-6 py-4"><div className="w-4 h-4 rounded-sm shadow-sm flex-shrink-0" style={{ backgroundColor: cat.color }} /><h2 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex-1">{cat.name}</h2><div className="px-3 py-1 bg-white border border-slate-100 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest shadow-sm">{catNodes.length} Nodes</div></div><div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">{catNodes.map(node => (<div key={node.id} className="relative group"><div className="transform transition-all duration-300 hover:-translate-y-1 hover:shadow-xl hover:shadow-slate-200/50"><BlueprintCard id={node.id} data={{ ...node.data, settings, appearance, onEdit: (id) => setEditingNode(id), onDelete: (id) => setNodes(nds => nds.filter(n => n.id !== id)), onDuplicate: handleDuplicateNode }} type="blueprintNode" dragging={false} zIndex={1} isConnectable={false} xPos={0} yPos={0} selected={false} /></div><div className="absolute top-[12px] left-[12px] flex gap-1 animate-in fade-in slide-in-from-top-1 duration-300 z-50"><button onClick={() => handleLocateOnCanvas(node.id)} className="p-1.5 bg-white text-blue-600 rounded shadow-sm border border-slate-200 hover:bg-blue-600 hover:text-white transition-all transform active:scale-90" title={t('locate_on_canvas')}><Crosshair size={14} strokeWidth={2.5} /></button></div></div>))}</div></section>); })}</div>)}
      </main>

      {editingNode && (<EditorModal node={nodes.find(n => n.id === editingNode)!} settings={settings} onClose={() => setEditingNode(null)} onSave={(data) => { setNodes(nds => nds.map(n => n.id === editingNode ? { ...n, data: { ...n.data, ...data } } : n)); setEditingNode(null); }} language={appearance.language} />)}
      {editingEdge && (<EdgeEditorModal edge={edges.find(e => e.id === editingEdge)!} settings={settings} onClose={() => setEditingEdge(null)} onSave={(data) => { const connType = settings.connectionTypes.find(t => t.id === data.typeId); setEdges(eds => eds.map(e => e.id === editingEdge ? { ...e, label: data.label, data: { ...e.data, typeId: data.typeId }, markerEnd: data.hasArrow ? { type: MarkerType.ArrowClosed, color: connType?.color || '#94a3b8' } : undefined } : e)); setEditingEdge(null); }} language={appearance.language} />)}
      {showStudioSettings && (<StudioSettingsModal settings={settings} appearance={appearance} initialTab={showStudioSettings.initialTab} onClose={() => setShowStudioSettings(null)} onSave={(s, a) => { setSettings(s); setAppearance(a); setShowStudioSettings(null); }} />)}
      {showExportModal && (<ExportImageModal nodes={nodes} edges={edges} settings={settings} appearance={appearance} activeTableFilters={activeTableFilters} activeLogicFilters={activeLogicFilters} activeEdgeFilters={activeEdgeFilters} activeTagFilters={activeTagFilters} searchQuery={searchQuery} onClose={() => setShowExportModal(false)} />)}
    </div>
  );
}

export default function App() { return (<ReactFlowProvider><BlueprintStudio /></ReactFlowProvider>); }

