  color: string;
  isDefault?: boolean;
}

export interface LogicCategory {
  id: string;
  name: string;
  color: string;
  isDefault?: boolean;
}

export interface DataSource {
  id: string;
  name: string;
}

export type LabelPosition = 'center' | 'source' | 'target';

export interface ConnectionType {
  id: string;
  name: string;
  color: string;
  width: number;
  dashStyle: 'solid' | 'dashed' | 'dotted';
  labelPosition?: LabelPosition;
